const TRANSLATIONS: Record<MossLocaleCode, Record<TranslationKey, string>> = {
  en: EN_TRANSLATIONS,
  "zh-CN": ZH_TRANSLATIONS,
};

export function translateMoss(locale: MossLocaleCode, key: TranslationKey): string {
  return TRANSLATIONS[locale]?.[key] ?? EN_TRANSLATIONS[key] ?? key;
}

export function formatMossTranslation(
  locale: MossLocaleCode,
  key: TranslationKey,
  values: Record<string, string | number>,
): string {
  return translateMoss(locale, key).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, name: string) => {
    const value = values[name];
    return value == null ? match : String(value);
  });
}

interface MossLocalizationContextValue {
  locale: MossLocaleCode;
  t: (key: TranslationKey) => string;
  format: (key: TranslationKey, values: Record<string, string | number>) => string;
}

// Unwrapped callers (unit tests that render without MossLocalizationProvider)
// stay on English so upstream transcript assertions keep matching. The
// provider below still resolves settings, which default to zh-CN.
const fallbackLocale = "en" satisfies MossLocaleCode;
const MossLocalizationContext = createContext<MossLocalizationContextValue>({
  locale: fallbackLocale,
  t: (key) => translateMoss(fallbackLocale, key),
  format: (key, values) => formatMossTranslation(fallbackLocale, key, values),
});

export function MossLocalizationProvider({
  children,
  localeOverride,
}: {
  children: ReactNode;
  localeOverride?: MossLocaleCode;
}) {
  const { settings } = useAppSettings();
  const locale = useMemo(
    () => resolveMossLocale(localeOverride ?? settings.localeOverride),
    [localeOverride, settings.localeOverride],
  );

  useEffect(() => {
    document.documentElement.lang = locale;
    document.documentElement.dataset.mossLocale = locale;
    void window.desktopBridge?.setUiLocale?.(locale).catch(() => undefined);
  }, [locale]);

  const value = useMemo<MossLocalizationContextValue>(
    () => ({
      locale,
      t: (key) => translateMoss(locale, key),
      format: (key, values) => formatMossTranslation(locale, key, values),
    }),
    [locale],
  );

  return (
    <MossLocalizationContext.Provider value={value}>{children}</MossLocalizationContext.Provider>
  );
}

export function useTranslation() {
  return useContext(MossLocalizationContext);
}

/** Renders children in one locale without reading app settings. */
export function MossLocaleScope({
  locale,
  children,
}: {
  locale: MossLocaleCode;
  children: ReactNode;
}) {
  const value = useMemo<MossLocalizationContextValue>(
    () => ({
      locale,
      t: (key) => translateMoss(locale, key),
      format: (key, values) => formatMossTranslation(locale, key, values),
    }),
    [locale],
  );
  return (
    <MossLocalizationContext.Provider value={value}>{children}</MossLocalizationContext.Provider>
  );
}
